    function pad(n) { return String(n).padStart(2, '0'); }

    function updateAllTimers() {
        var now = Math.floor(Date.now() / 1000);
        document.querySelectorAll('.adv-timer').forEach(function (el) {
            var deadline = parseInt(el.getAttribute('data-deadline'), 10);
            var textEl = el.querySelector('.timer-text');
            if (!deadline || !textEl) return;

            var diff = deadline - now;
            if (diff <= 0) {
                textEl.textContent = 'Closed';
                el.style.background = '#f8d7da';
                el.style.borderColor = '#dc3545';
                el.style.color = '#721c24';
                return;
            }

            var d = Math.floor(diff / 86400);
            var h = Math.floor((diff % 86400) / 3600);
            var m = Math.floor((diff % 3600) / 60);
            var s = diff % 60;

            var txt = '';
            if (d > 0) txt += d + 'd ';
            txt += pad(h) + 'h ' + pad(m) + 'm ' + pad(s) + 's';
            textEl.textContent = txt;
        });
    }

    updateAllTimers();
    setInterval(updateAllTimers, 1000);
});
